struct SLPBuilder {
  typedef SLP Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_PROBLEM_ID(::flatbuffers::Offset<::flatbuffers::String> PROBLEM_ID) {
    fbb_.AddOffset(SLP::VT_PROBLEM_ID, PROBLEM_ID);
  }
  void add_NAME(::flatbuffers::Offset<::flatbuffers::String> NAME) {
    fbb_.AddOffset(SLP::VT_NAME, NAME);
  }
  void add_KIND(slpProblemKind KIND) {
    fbb_.AddElement<uint8_t>(SLP::VT_KIND, static_cast<uint8_t>(KIND), 0);
  }
  void add_PROPAGATOR_PORT_ID(::flatbuffers::Offset<::flatbuffers::String> PROPAGATOR_PORT_ID) {
    fbb_.AddOffset(SLP::VT_PROPAGATOR_PORT_ID, PROPAGATOR_PORT_ID);
  }
  void add_OBJECTIVE_EVALUATOR_PORT_ID(::flatbuffers::Offset<::flatbuffers::String> OBJECTIVE_EVALUATOR_PORT_ID) {
    fbb_.AddOffset(SLP::VT_OBJECTIVE_EVALUATOR_PORT_ID, OBJECTIVE_EVALUATOR_PORT_ID);
  }
  void add_VARIABLES(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<SLPVariable>>> VARIABLES) {
    fbb_.AddOffset(SLP::VT_VARIABLES, VARIABLES);
  }
  void add_GOALS(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<SLPGoal>>> GOALS) {
    fbb_.AddOffset(SLP::VT_GOALS, GOALS);
  }
  void add_OBJECTIVE(::flatbuffers::Offset<SLPObjective> OBJECTIVE) {
    fbb_.AddOffset(SLP::VT_OBJECTIVE, OBJECTIVE);
  }
  void add_CONSTRAINTS(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<SLPNonlinearConstraint>>> CONSTRAINTS) {
    fbb_.AddOffset(SLP::VT_CONSTRAINTS, CONSTRAINTS);
  }
  void add_SETTINGS(::flatbuffers::Offset<SLPSolverSettings> SETTINGS) {
    fbb_.AddOffset(SLP::VT_SETTINGS, SETTINGS);
  }
  void add_REPORT(::flatbuffers::Offset<SLPSolverReport> REPORT) {
    fbb_.AddOffset(SLP::VT_REPORT, REPORT);
  }
  void add_CREATED_AT(::flatbuffers::Offset<::flatbuffers::String> CREATED_AT) {
    fbb_.AddOffset(SLP::VT_CREATED_AT, CREATED_AT);
  }
  void add_ATTESTATION(::flatbuffers::Offset<SLPAttestation> ATTESTATION) {
    fbb_.AddOffset(SLP::VT_ATTESTATION, ATTESTATION);
  }
  explicit SLPBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<SLP> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<SLP>(end);
    fbb_.Required(o, SLP::VT_PROBLEM_ID);
    fbb_.Required(o, SLP::VT_PROPAGATOR_PORT_ID);
    fbb_.Required(o, SLP::VT_ATTESTATION);
    return o;
  }
};

inline ::flatbuffers::Offset<SLP> CreateSLP(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> PROBLEM_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> NAME = 0,
    slpProblemKind KIND = slpProblemKind::UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::String> PROPAGATOR_PORT_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> OBJECTIVE_EVALUATOR_PORT_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<SLPVariable>>> VARIABLES = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<SLPGoal>>> GOALS = 0,
    ::flatbuffers::Offset<SLPObjective> OBJECTIVE = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<SLPNonlinearConstraint>>> CONSTRAINTS = 0,
    ::flatbuffers::Offset<SLPSolverSettings> SETTINGS = 0,
    ::flatbuffers::Offset<SLPSolverReport> REPORT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> CREATED_AT = 0,
    ::flatbuffers::Offset<SLPAttestation> ATTESTATION = 0) {
  SLPBuilder builder_(_fbb);
  builder_.add_ATTESTATION(ATTESTATION);
  builder_.add_CREATED_AT(CREATED_AT);
  builder_.add_REPORT(REPORT);
  builder_.add_SETTINGS(SETTINGS);
  builder_.add_CONSTRAINTS(CONSTRAINTS);
  builder_.add_OBJECTIVE(OBJECTIVE);
  builder_.add_GOALS(GOALS);
  builder_.add_VARIABLES(VARIABLES);
  builder_.add_OBJECTIVE_EVALUATOR_PORT_ID(OBJECTIVE_EVALUATOR_PORT_ID);
  builder_.add_PROPAGATOR_PORT_ID(PROPAGATOR_PORT_ID);
  builder_.add_NAME(NAME);
  builder_.add_PROBLEM_ID(PROBLEM_ID);
  builder_.add_KIND(KIND);
  return builder_.Finish();
}

